    // step executes one step of the machine, running each of the threads
    // on runq and appending new threads to nextq.
    // The step processes the rune c (which may be endOfText),
    // which starts at position pos and ends at nextPos.
    // nextCond gives the setting for the empty-width flags after c.
    void rec::step(machine* m, queue* runq, queue* nextq, int pos, int nextPos, gocpp::rune c, lazyFlag* nextCond)
    {
        auto longest = m->re->longest;
        for(auto j = 0; j < len(runq->dense); j++)
        {
            auto d = & runq->dense[j];
            auto t = d->t;
            if(t == nullptr)
            {
                continue;
            }
            if(longest && m->matched && len(t->cap) > 0 && m->matchcap[0] < t->cap[0])
            {
                m->pool = append(m->pool, t);
                continue;
            }
            auto i = t->inst;
            auto add = false;
            //Go switch emulation
            {
                auto condition = i->Op;
                int conditionId = -1;
                if(condition == syntax::InstMatch) { conditionId = 0; }
                else if(condition == syntax::InstRune) { conditionId = 1; }
                else if(condition == syntax::InstRune1) { conditionId = 2; }
                else if(condition == syntax::InstRuneAny) { conditionId = 3; }
                else if(condition == syntax::InstRuneAnyNotNL) { conditionId = 4; }
                switch(conditionId)
                {
                    default:
                        gocpp::panic("bad inst"_s);
                        break;

                    case 0:
                        if(len(t->cap) > 0 && (! longest || ! m->matched || m->matchcap[1] < pos))
                        {
                            t->cap[1] = pos;
                            copy(m->matchcap, t->cap);
                        }
                        if(! longest)
                        {
                            // First-match mode: cut off all lower-priority threads.
                            for(auto [gocpp_ignored, d] : runq->dense.make_slice(j + 1))
                            {
                                if(d.t != nullptr)
                                {
                                    m->pool = append(m->pool, d.t);
                                }
                            }
                            runq->dense = runq->dense.make_slice(0, 0);
                        }
                        m->matched = true;
                        break;

                    case 1:
                        add = rec::MatchRune(gocpp::recv(i), c);
                        break;
                    case 2:
                        add = c == i->Rune[0];
                        break;
                    case 3:
                        add = true;
                        break;
                    case 4:
                        add = c != '\n';
                        break;
                }
            }
            if(add)
            {
                t = rec::add(gocpp::recv(m), nextq, i->Out, nextPos, t->cap, nextCond, t);
            }
            if(t != nullptr)
            {
                m->pool = append(m->pool, t);
            }
        }
        runq->dense = runq->dense.make_slice(0, 0);
    }

    // add adds an entry to q for pc, unless the q already has such an entry.
    // It also recursively adds an entry for all instructions reachable from pc by following
    // empty-width conditions satisfied by cond.  pos gives the current position
    // in the input.
    thread* rec::add(machine* m, queue* q, uint32_t pc, int pos, gocpp::slice<int> cap, lazyFlag* cond, thread* t)
    {
        Again:
        if(pc == 0)
        {
            return t;
        }
        if(auto j = q->sparse[pc]; j < uint32_t(len(q->dense)) && q->dense[j].pc == pc)
        {
            return t;
        }

        auto j = len(q->dense);
        q->dense = q->dense.make_slice(0, j + 1);
        auto d = & q->dense[j];
        d->t = nullptr;
        d->pc = pc;
        q->sparse[pc] = uint32_t(j);

        auto i = & m->p->Inst[pc];
        //Go switch emulation
        {
            auto condition = i->Op;
            int conditionId = -1;
            if(condition == syntax::InstFail) { conditionId = 0; }
            else if(condition == syntax::InstAlt) { conditionId = 1; }
            else if(condition == syntax::InstAltMatch) { conditionId = 2; }
            else if(condition == syntax::InstEmptyWidth) { conditionId = 3; }
            else if(condition == syntax::InstNop) { conditionId = 4; }
            else if(condition == syntax::InstCapture) { conditionId = 5; }
            else if(condition == syntax::InstMatch) { conditionId = 6; }
            else if(condition == syntax::InstRune) { conditionId = 7; }
            else if(condition == syntax::InstRune1) { conditionId = 8; }
            else if(condition == syntax::InstRuneAny) { conditionId = 9; }
            else if(condition == syntax::InstRuneAnyNotNL) { conditionId = 10; }
            switch(conditionId)
            {
                default:
                    gocpp::panic("unhandled"_s);
                    break;
                case 0:
                    break;
                // nothing
                case 1:
                case 2:
                    t = rec::add(gocpp::recv(m), q, i->Out, pos, cap, cond, t);
                    pc = i->Arg;
                    goto Again;
                    break;
                case 3:
                    if(rec::match(gocpp::recv(cond), syntax::EmptyOp(i->Arg)))
                    {
                        pc = i->Out;
                        goto Again;
                    }
                    break;
                case 4:
                    pc = i->Out;
                    goto Again;
                    break;
                case 5:
                    if(int(i->Arg) < len(cap))
                    {
                        auto opos = cap[i->Arg];
                        cap[i->Arg] = pos;
                        rec::add(gocpp::recv(m), q, i->Out, pos, cap, cond, nullptr);
                        cap[i->Arg] = opos;
                    }
                    else
                    {
                        pc = i->Out;
                        goto Again;
                    }
                    break;
                case 6:
                case 7:
                case 8:
                case 9:
                case 10:
                    if(t == nullptr)
                    {
                        t = rec::alloc(gocpp::recv(m), i);
                    }
                    else
                    {
                        t->inst = i;
                    }
                    if(len(cap) > 0 && & t->cap[0] != & cap[0])
                    {
                        copy(t->cap, cap);
                    }
                    d->t = t;
                    t = nullptr;
                    break;
            }
        }
        return t;
    }

    
